The current hope-ui source targets Solid 2 beta.32 and uses ThemeProvider with the hope preset. An accessible date-selection calendar with themed header and month grid.

Original documented example:
```tsx
import { Calendar } from "@hope-ui/components/calendar";
import { createSignal } from "solid-js";
import { formatSelection, REFERENCE_DATE, type SelectionValue } from "./data";

// The default: single selection, composed from the compound parts so the anatomy is concrete —
// Header (Prev / Heading / Next) over the month Grid. Controlled (`value`/`onValueChange`): the
// committed date is mirrored into a signal that drives both the calendar and the readout. Arrow keys /
// Home / End / PageUp/Down move the roving focus; Enter, Space, or a click selects.
export function CalendarBasicDemo() {
  const [value, setValue] = createSignal<SelectionValue>(null);

  return (
    <div class="flex flex-col items-center gap-3">
      <Calendar.Root defaultFocusedValue={REFERENCE_DATE} value={value()} onValueChange={setValue}>
        <Calendar.Header>
          <Calendar.PrevButton />
          <Calendar.Heading />
          <Calendar.NextButton />
        </Calendar.Header>
        <Calendar.Grid />
      </Calendar.Root>
      <output class="text-sm text-foreground-muted">Selected: {formatSelection(value())}</output>
    </div>
  );
}

```

Supporting original data module (data.ts):
```tsx
import { CalendarDate } from "@internationalized/date";

// A fixed anchor month shared by every Calendar demo. The calendar seeds its visible month from
// `defaultFocusedValue`; leaving it to `today()` would differ between build time (this SSG site is
// prerendered) and view time, so the server HTML and the hydrated client would disagree on the whole
// grid — a hydration mismatch. A stable date keeps the prerendered markup and the client identical.
export const REFERENCE_DATE = new CalendarDate(2020, 9, 7);

// The value union the calendar hands `onValueChange`, described structurally so the demos read it
// without importing `@hope-ui/primitives` — the themeable component is the public surface.
type DateRangeValue = { start: CalendarDate; end: CalendarDate };
export type SelectionValue = CalendarDate | DateRangeValue | CalendarDate[] | null;

/** Render any selection as ISO `YYYY-MM-DD` text for a demo's readout (`CalendarDate.toString()`). */
export function formatSelection(value: SelectionValue): string {
  if (value == null) {
    return "—";
  }
  if (Array.isArray(value)) {
    return value.length ? value.map(String).join(", ") : "—";
  }
  if ("start" in value) {
    return `${value.start} → ${value.end}`;
  }
  return String(value);
}

```

The current hope-ui source targets Solid 2 beta.32 and uses ThemeProvider with the hope preset. A close button that adapts its icon and interaction states to its surface.

Original documented example:
```tsx
import { CloseButton } from "@hope-ui/components/close-button";
import type { JSX } from "@solidjs/web";

// Live demo for the "Adapts to the surface" section.
//
// CloseButton asserts no color of its own: the glyph inherits `currentColor` and its hover/press
// wash + focus ring derive from it, so one component reads correctly on any surface. Each cell sets
// its own background + text color; the same `<CloseButton />` picks that up with zero configuration.
// (The colored surface classes are plain divs — no inline <svg> — but this lives in .tsx to keep the
// stacked layout out of the MDX flow.)
function Cell(props: { class: string; label: string }): JSX.Element {
  return (
    <div class={`flex items-center justify-between gap-6 rounded-lg p-4 ${props.class}`}>
      <span class="text-sm font-medium">{props.label}</span>
      <CloseButton />
    </div>
  );
}

export function CloseButtonSurfacesDemo() {
  return (
    <div class="flex w-full max-w-md flex-col gap-3 not-prose">
      {/* Light surface: dark text -> a dark, low-alpha wash. */}
      <Cell class="bg-surface text-foreground border border-subtle" label="On a light surface" />
      {/* Soft-tinted surface: role-emphasis text -> a role-tinted wash. */}
      <Cell class="bg-primary-soft text-primary-emphasis" label="On a soft surface" />
      {/* Solid colored surface: on-color text -> a light wash. */}
      <Cell class="bg-primary text-on-primary" label="On a solid surface" />
      {/* Dark surface: light text -> a light, low-alpha wash. */}
      <Cell class="bg-surface-inverse text-on-inverse" label="On a dark surface" />
    </div>
  );
}

```

